/** Resolve a wall time, choosing the earlier occurrence in a fold and moving
 * forward by the gap when a clock skips the requested time. */
export function localDayHour(day: string, hour: number, timeZone: string): IsoTimestamp {
  const [year, month, date] = day.split("-").map(Number);
  const wall = Date.UTC(year, month - 1, date, hour);
  const offsets = new Set<number>();
